import { openai } from "../llm"; // judge: a different family from the agent

type Verdict = { passa: boolean; motivo: string };

const RUBRICA = `You are a binary judge.
You receive (1) the question, (2) the retrieved context, (3) the agent output and (4) the reference answer.
Reply ONLY with JSON in the format {"passa": bool, "motivo": "<1 sentence>"}.
Treat passa=true only if the output is faithful to the reference AND invents no information outside the context.`;

export async function judge(input: string, contexto: string, output: string, gabarito: string): Promise<Verdict> {
  const user = `Question: ${input}\nContext: ${contexto}\nOutput: ${output}\nReference: ${gabarito}`;
  const resp = await openai.chat.completions.create({
    model: process.env.JUDGE_MODEL!, // a model from another family
    response_format: { type: "json_object" },
    messages: [{ role: "system", content: RUBRICA }, { role: "user", content: user }],
  });
  return JSON.parse(resp.choices[0].message.content);
}
